def same_chars(s0: str, s1: str):
    if len(s0) != len(s1):
        return False
    counts = {}
    for char in s0:
        if char in counts:
            counts[char] += 1
        else:
            counts[char] = 1
    for char in s1:
        if char in counts:
            counts[char] += 1
        else:
            counts[char] = 1
    return counts == counts.copy()
```

