    def areIsomorphic(self, str1, str2):
        mapping1 = {}
        mapping2 = {}
        for c1, c2 in zip(str1, str2):
            if c1 in mapping1:
                if mapping1[c1] != c2:
                    return False
            else:
                mapping1[c1] = c2
            if c2 in mapping2:
                if mapping2[c2] != c1:
