def next_generation(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    new_grid = [[0] * cols for _ in range(rows)]

    for i in range(rows):
        for j in range(cols):
            live_neighbors = 0
            for dx in (-1, 0, 1):
                for dy in (-1, 0, 1):
                    if dx == 0 and dy == 0:
                        continue
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < rows and 0 <= nj < cols:
                        if grid[ni][nj] == 1:
                            live_neighbors += 1

            if grid[i][j] == 1:
                new_grid[i][j] = 1 if live_neighbors >= 5 else 0
            else:
                new_grid[i][j] = 0

    return new_grid
